using System.Text.Json;
using System.Data;
using Microsoft.EntityFrameworkCore;
using Topstar.Application.Campaigns;
using Topstar.Application.Finance;
using Topstar.Application.Schedules;
using Topstar.Application.Disputes;
using Topstar.Infrastructure.Entities;
using Topstar.Infrastructure.Persistence;
namespace Topstar.Infrastructure.Disputes;
public sealed class DisputeService(TopstarDbContext db):IDisputeService
{
 public async Task<DisputePortal> GetPortalAsync(Guid userId,bool isBrand,CancellationToken ct=default, Topstar.Application.Common.ListWindow? window = null, Guid? campaignId = null)
 {
  var candidates=await(from p in db.Participations.AsNoTracking() join c in db.Campaigns.AsNoTracking() on p.CampaignId equals c.Id join b in db.BrandProfiles.AsNoTracking() on c.BrandProfileId equals b.Id join k in db.KocProfiles.AsNoTracking() on p.KocProfileId equals k.Id where (p.Status=="Confirmed"||p.Status=="Completed")&&(isBrand?b.UserId==userId:k.UserId==userId)&&(!campaignId.HasValue||c.Id==campaignId.Value) orderby c.Title select new DisputeCandidate(p.Id,c.Title,isBrand?k.DisplayName:b.CompanyName)).ToListAsync(ct);
  return new(candidates,await LoadCasesAsync(userId,isBrand,null,ct,window,campaignId));
 }
 public Task<IReadOnlyList<DisputeCaseItem>> GetAdminQueueAsync(string? status,CancellationToken ct=default, Topstar.Application.Common.ListWindow? window = null)=>LoadCasesAsync(null,false,Clean(status),ct,window);
 public async Task<DisputeCaseDetail?> GetDetailAsync(Guid userId,string role,Guid caseId,CancellationToken ct=default)
 {
  role=(Clean(role)??"").ToUpperInvariant();var isAdmin=role=="ADMIN";var isBrand=role=="BRAND";var cases=await LoadCasesAsync(isAdmin?null:userId,isBrand,null,ct);var item=cases.FirstOrDefault(x=>x.Id==caseId);if(item is null)return null;
  var rows=await(from m in db.DisputeMessages.AsNoTracking() join u in db.Users.AsNoTracking() on m.AuthorUserId equals u.Id where m.DisputeCaseId==caseId&&(isAdmin||m.Visibility=="Parties") orderby m.CreatedAtUtc select new DisputeMessageItem(m.Id,u.Email??"Người dùng",m.AuthorRole,m.Body,m.EvidenceUrl,m.Visibility,m.CreatedAtUtc)).ToListAsync(ct);
  var holds=isAdmin?await db.WalletTransactions.AsNoTracking().Where(x=>x.HoldDisputeCaseId==caseId&&x.Status==WalletStatuses.OnHold).Select(x=>x.Amount).ToListAsync(ct):[];
  return new(item,rows,DisputeTransitions.IsActive(item.Status),holds.Count,holds.Sum());
 }
 public async Task<DisputeResult> AddMessageAsync(Guid userId,string role,Guid caseId,string body,string? evidenceUrl,bool adminOnly,CancellationToken ct=default)
 {
  role=(Clean(role)??"").ToUpperInvariant();body=Clean(body)??"";evidenceUrl=Clean(evidenceUrl);if(role is not("ADMIN" or "BRAND" or "KOC")||body.Length is <2 or >2000)return Fail("Nội dung trao đổi phải từ 2–2.000 ký tự.");if(evidenceUrl is not null&&(evidenceUrl.Length>1000||!Uri.TryCreate(evidenceUrl,UriKind.Absolute,out var uri)||uri.Scheme is not("http" or "https")))return Fail("Link bằng chứng phải là URL http/https hợp lệ, tối đa 1.000 ký tự.");if(adminOnly&&role!="ADMIN")return Fail("Chỉ Admin được tạo ghi chú nội bộ.");
  var access=await(from d in db.DisputeCases join p in db.Participations on d.ParticipationId equals p.Id join c in db.Campaigns on p.CampaignId equals c.Id join b in db.BrandProfiles on c.BrandProfileId equals b.Id join k in db.KocProfiles on p.KocProfileId equals k.Id where d.Id==caseId select new{Case=d,BrandUser=b.UserId,KocUser=k.UserId}).FirstOrDefaultAsync(ct);if(access is null||role=="BRAND"&&access.BrandUser!=userId||role=="KOC"&&access.KocUser!=userId)return Fail("Không tìm thấy hồ sơ tranh chấp hoặc bạn không có quyền.");if(!DisputeTransitions.IsActive(access.Case.Status))return Fail("Tranh chấp đã đóng, không thể thêm trao đổi mới.");
  var now=DateTime.UtcNow;db.DisputeMessages.Add(new(){Id=Guid.NewGuid(),DisputeCaseId=caseId,AuthorUserId=userId,AuthorRole=role,Body=body,EvidenceUrl=evidenceUrl,Visibility=adminOnly?"AdminOnly":"Parties",CreatedAtUtc=now});Audit(userId,caseId,"AddMessage",new{Role=role,HasEvidence=evidenceUrl is not null,Visibility=adminOnly?"AdminOnly":"Parties"},now);
  if(!adminOnly){if(role=="BRAND")Notify(access.KocUser,"KOC","DisputeMessage","Có phản hồi mới trong tranh chấp",access.Case.Subject,access.Case.Id,now);else if(role=="KOC")Notify(access.BrandUser,"BRAND","DisputeMessage","Có phản hồi mới trong tranh chấp",access.Case.Subject,access.Case.Id,now);else{Notify(access.BrandUser,"BRAND","DisputeMessage","Admin có phản hồi mới",access.Case.Subject,access.Case.Id,now);Notify(access.KocUser,"KOC","DisputeMessage","Admin có phản hồi mới",access.Case.Subject,access.Case.Id,now);}}
  try{await db.SaveChangesAsync(ct);}catch(DbUpdateException){return Fail("Case vừa đóng hoặc dữ liệu đã thay đổi. Vui lòng tải lại.");}return Ok(adminOnly?"Đã lưu ghi chú nội bộ.":"Đã gửi phản hồi vào hồ sơ tranh chấp.");
 }
 public async Task<DisputeResult> OpenAsync(Guid userId,bool isBrand,Guid participationId,string category,string subject,string description,CancellationToken ct=default)
 {
  category=NormalizeCategory(category);subject=Clean(subject)??"";description=Clean(description)??"";
  if(!DisputeCategories.IsValid(category)||subject.Length is <5 or >200||description.Length is <10 or >2000)return Fail("Chọn loại hợp lệ; tiêu đề 5–200 ký tự và mô tả 10–2.000 ký tự.");
  var row=await(from p in db.Participations join c in db.Campaigns on p.CampaignId equals c.Id join b in db.BrandProfiles on c.BrandProfileId equals b.Id join k in db.KocProfiles on p.KocProfileId equals k.Id where p.Id==participationId&&(isBrand?b.UserId==userId:k.UserId==userId) select new{Participation=p,Campaign=c,BrandUser=b.UserId,KocUser=k.UserId}).FirstOrDefaultAsync(ct);
  if(row is null||row.Participation.Status is not("Confirmed" or "Completed"))return Fail("Không tìm thấy lượt tham gia hợp lệ để mở tranh chấp.");
  var now=DateTime.UtcNow;var item=new DisputeCaseEntity{Id=Guid.NewGuid(),ParticipationId=participationId,CreatedByUserId=userId,Category=category,Subject=subject,Description=description,Status=DisputeStatuses.Open,Priority=category is "Payment" or "Shipment"?"High":"Normal",IsActive=true,CreatedAtUtc=now};db.DisputeCases.Add(item);History(item.Id,null,DisputeStatuses.Open,description,userId,now);Audit(userId,item.Id,"Open",new{category,subject},now);
  Notify(isBrand?row.KocUser:row.BrandUser,isBrand?"KOC":"BRAND","Dispute","Có tranh chấp mới",$"{subject} · {row.Campaign.Title}",item.Id,now);var admins=await(from u in db.Users.AsNoTracking() join ur in db.UserRoles.AsNoTracking() on u.Id equals ur.UserId join r in db.Roles.AsNoTracking() on ur.RoleId equals r.Id where r.Code=="ADMIN" select u.Id).Distinct().ToListAsync(ct);foreach(var admin in admins)Notify(admin,"ADMIN","Dispute","Tranh chấp mới cần xử lý",subject,item.Id,now);
  try{await db.SaveChangesAsync(ct);}catch(DbUpdateException){return Fail("Đã có tranh chấp đang mở cùng loại cho lượt tham gia này.");}return Ok("Đã mở tranh chấp và thông báo cho Admin.");
 }
 public async Task<DisputeResult> CancelAsync(Guid userId,Guid id,string reason,CancellationToken ct=default)
 {
  reason=Clean(reason)??"";if(reason.Length is 0 or >1000)return Fail("Nhập lý do hủy, tối đa 1.000 ký tự.");var item=await db.DisputeCases.FirstOrDefaultAsync(x=>x.Id==id&&x.CreatedByUserId==userId,ct);if(item is null)return Fail("Không tìm thấy tranh chấp.");if(!DisputeTransitions.CanCancel(item.Status))return Fail("Chỉ tranh chấp mới mở mới được người tạo hủy.");return await Change(item,DisputeStatuses.Cancelled,reason,userId,item.ParticipationId,ct);
 }
 public async Task<DisputeResult> TakeAsync(Guid admin,Guid id,CancellationToken ct=default)
 {
  var item=await db.DisputeCases.FirstOrDefaultAsync(x=>x.Id==id,ct);if(item is null)return Fail("Không tìm thấy tranh chấp.");if(!DisputeTransitions.CanTake(item.Status))return Fail("Tranh chấp đã được tiếp nhận.");item.AssignedAdminUserId=admin;return await Change(item,DisputeStatuses.InReview,"Admin tiếp nhận xử lý",admin,item.ParticipationId,ct);
 }
 public async Task<DisputeResult> DecideAsync(Guid admin,Guid id,string decision,string resolution,CancellationToken ct=default)
 {
  decision=Clean(decision)??"";resolution=Clean(resolution)??"";if(decision is not(DisputeStatuses.Resolved or DisputeStatuses.Rejected)||resolution.Length is <10 or >2000)return Fail("Chọn chấp nhận hoặc bác khiếu nại và nhập kết luận 10–2.000 ký tự.");var item=await db.DisputeCases.FirstOrDefaultAsync(x=>x.Id==id,ct);if(item is null)return Fail("Không tìm thấy tranh chấp.");if(!DisputeTransitions.CanResolve(item.Status))return Fail("Tranh chấp đã có kết quả cuối.");item.AssignedAdminUserId=admin;item.ResolutionNote=resolution;item.ResolvedAtUtc=DateTime.UtcNow;return await Change(item,decision,resolution,admin,item.ParticipationId,ct);
 }
 public async Task<DisputeResult> CancelCampaignAsync(Guid admin,Guid caseId,string reason,CancellationToken ct=default)
 {
  reason=Clean(reason)??"";if(reason.Length is <10 or >900)return Fail("Lý do hủy campaign phải từ 10–900 ký tự.");await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);
  var row=await(from d in db.DisputeCases join p in db.Participations on d.ParticipationId equals p.Id join c in db.Campaigns on p.CampaignId equals c.Id join b in db.BrandProfiles on c.BrandProfileId equals b.Id where d.Id==caseId select new{Case=d,Campaign=c,BrandUser=b.UserId}).FirstOrDefaultAsync(ct);if(row is null)return Fail("Không tìm thấy dispute hoặc campaign.");if(!row.Case.IsActive)return Fail("Chỉ dispute đang hoạt động mới được dùng để hủy campaign.");if(row.Campaign.Status!=CampaignStatuses.InProgress)return Fail("Chỉ campaign đang thực hiện mới được Admin hủy theo dispute.");
  var now=DateTime.UtcNow;row.Campaign.Status=CampaignStatuses.Cancelled;row.Campaign.CancellationDisputeCaseId=caseId;row.Campaign.CancelledByUserId=admin;row.Campaign.CancelledAtUtc=now;row.Campaign.CancellationReason=reason;row.Campaign.UpdatedAtUtc=now;db.CampaignStatusHistories.Add(new(){Id=Guid.NewGuid(),CampaignId=row.Campaign.Id,FromStatus=CampaignStatuses.InProgress,ToStatus=CampaignStatuses.Cancelled,Note=$"Dispute {caseId}: {reason}",ActorUserId=admin,CreatedAtUtc=now});
  var participations=await db.Participations.Where(x=>x.CampaignId==row.Campaign.Id&&x.Status=="Confirmed").ToListAsync(ct);foreach(var p in participations){p.Status="Cancelled";p.UpdatedAtUtc=now;db.ParticipationStatusHistories.Add(new(){Id=Guid.NewGuid(),ParticipationId=p.Id,FromStatus="Confirmed",ToStatus="Cancelled",Note=$"Campaign cancelled by dispute {caseId}",ActorUserId=admin,CreatedAtUtc=now});}
  var participationIds=participations.Select(x=>x.Id).ToArray();var schedules=await db.Schedules.Where(x=>participationIds.Contains(x.ParticipationId)&&x.Status!="Cancelled").ToListAsync(ct);foreach(var s in schedules){var from=s.Status;var isLate=ScheduleTransitions.IsLateCancellation(from,s.StartsAtUtc,now);s.Status=ScheduleStatuses.Cancelled;s.IsLateCancellation=isLate;s.LateCancellationThresholdHours=isLate?ScheduleTransitions.LateCancellationHours:null;s.CancelledAtUtc=now;s.CancelledByUserId=admin;s.UpdatedAtUtc=now;db.ScheduleStatusHistories.Add(new(){Id=Guid.NewGuid(),ScheduleId=s.Id,FromStatus=from,ToStatus=ScheduleStatuses.Cancelled,StartsAtUtc=s.StartsAtUtc,EndsAtUtc=s.EndsAtUtc,Note=$"Campaign cancelled by dispute {caseId}"+(isLate?$" · Hủy sát giờ ≤ {ScheduleTransitions.LateCancellationHours}h":""),ActorUserId=admin,CreatedAtUtc=now});}
  // Chỉ giữ khoản thu nhập của KOC thuộc hồ sơ tranh chấp. Các KOC không liên quan
  // không được bị đóng băng thu nhập chỉ vì cùng tham gia một chiến dịch.
  var wallets=await db.WalletTransactions.Where(x=>x.ParticipationId==row.Case.ParticipationId&&(x.Status==WalletStatuses.Pending||x.Status==WalletStatuses.Available)).ToListAsync(ct);foreach(var w in wallets){var from=w.Status;w.Status=WalletStatuses.OnHold;w.HoldReason=$"Campaign cancelled by dispute {caseId}";w.HoldDisputeCaseId=caseId;w.UpdatedAtUtc=now;db.WalletTransactionStatusHistories.Add(new(){Id=Guid.NewGuid(),WalletTransactionId=w.Id,FromStatus=from,ToStatus=WalletStatuses.OnHold,Reason=w.HoldReason,ActorUserId=admin,DisputeCaseId=caseId,CreatedAtUtc=now});}
  if(row.Case.Status==DisputeStatuses.Open){row.Case.Status=DisputeStatuses.InReview;row.Case.AssignedAdminUserId=admin;row.Case.UpdatedAtUtc=now;History(caseId,DisputeStatuses.Open,DisputeStatuses.InReview,"Admin tiếp nhận và hủy campaign",admin,now);}
  var kocUsers=await(from p in db.Participations.AsNoTracking() join k in db.KocProfiles.AsNoTracking() on p.KocProfileId equals k.Id where p.CampaignId==row.Campaign.Id select k.UserId).Distinct().ToListAsync(ct);Notify(row.BrandUser,"BRAND","CampaignCancelled","Admin đã hủy campaign",reason,caseId,now);foreach(var user in kocUsers)Notify(user,"KOC","CampaignCancelled","Admin đã hủy campaign",reason,caseId,now);Audit(admin,caseId,"CancelCampaign",new{CampaignId=row.Campaign.Id,Reason=reason,ParticipationCount=participations.Count,WalletHoldCount=wallets.Count},now);
  try{await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);}catch(DbUpdateException){await tx.RollbackAsync(ct);return Fail("Dữ liệu vừa thay đổi hoặc không thể ghi đầy đủ lịch sử. Vui lòng tải lại.");}return Ok("Đã hủy campaign, hủy lịch liên quan và tạm giữ các khoản earning chưa payout.");
 }
 public async Task<DisputeResult> ReleaseEarningsAsync(Guid admin,Guid caseId,string reason,CancellationToken ct=default)
 {
  reason=Clean(reason)??"";if(reason.Length is <10 or >900)return Fail("Lý do giải phóng earning phải từ 10–900 ký tự.");await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);var item=await db.DisputeCases.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==caseId,ct);if(item is null)return Fail("Không tìm thấy dispute.");
  if(!DisputeTransitions.CanReleaseEarnings(item.Status))return Fail("Chỉ giải phóng earning sau khi dispute có kết quả cuối.");var wallets=await db.WalletTransactions.Where(x=>x.HoldDisputeCaseId==caseId&&x.Status==WalletStatuses.OnHold).ToListAsync(ct);if(wallets.Count==0)return Fail("Không còn earning nào đang bị giữ bởi dispute này.");var now=DateTime.UtcNow;foreach(var w in wallets){w.Status=WalletStatuses.Available;w.HoldReason=null;w.HoldDisputeCaseId=null;w.AvailableAtUtc=now;w.UpdatedAtUtc=now;db.WalletTransactionStatusHistories.Add(new(){Id=Guid.NewGuid(),WalletTransactionId=w.Id,FromStatus=WalletStatuses.OnHold,ToStatus=WalletStatuses.Available,Reason=reason,ActorUserId=admin,DisputeCaseId=caseId,CreatedAtUtc=now});}
  var walletIds=wallets.Select(x=>x.Id).ToArray();var users=await(from w in db.WalletTransactions.AsNoTracking() join k in db.KocProfiles.AsNoTracking() on w.KocProfileId equals k.Id where walletIds.Contains(w.Id) select k.UserId).Distinct().ToListAsync(ct);foreach(var user in users)Notify(user,"KOC","WalletRelease","Earning đã được giải phóng",reason,caseId,now);Audit(admin,caseId,"ReleaseEarnings",new{TransactionCount=wallets.Count,Amount=wallets.Sum(x=>x.Amount),Reason=reason},now);try{await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);}catch(DbUpdateException){await tx.RollbackAsync(ct);return Fail("Dữ liệu tài chính vừa thay đổi. Vui lòng tải lại.");}return Ok($"Đã giải phóng {wallets.Count} khoản earning về Available.");
 }
 private async Task<DisputeResult> Change(DisputeCaseEntity item,string to,string note,Guid actor,Guid? notifyParticipation,CancellationToken ct)
 {
  var now=DateTime.UtcNow;var from=item.Status;item.Status=to;item.IsActive=DisputeTransitions.IsActive(to);item.UpdatedAtUtc=now;History(item.Id,from,to,note,actor,now);Audit(actor,item.Id,to,new{FromStatus=from,Note=note},now);
  if(notifyParticipation.HasValue){var users=await(from p in db.Participations.AsNoTracking() join c in db.Campaigns.AsNoTracking() on p.CampaignId equals c.Id join b in db.BrandProfiles.AsNoTracking() on c.BrandProfileId equals b.Id join k in db.KocProfiles.AsNoTracking() on p.KocProfileId equals k.Id where p.Id==notifyParticipation.Value select new{Brand=b.UserId,Koc=k.UserId}).FirstAsync(ct);var title=to==DisputeStatuses.InReview?"Admin đã tiếp nhận tranh chấp":to==DisputeStatuses.Cancelled?"Tranh chấp đã được hủy":"Tranh chấp đã có kết quả";Notify(users.Brand,"BRAND","Dispute",title,note,item.Id,now);Notify(users.Koc,"KOC","Dispute",title,note,item.Id,now);}
  try{await db.SaveChangesAsync(ct);}catch(DbUpdateConcurrencyException){return Fail("Trạng thái vừa thay đổi. Vui lòng tải lại.");}return Ok(to switch{DisputeStatuses.InReview=>"Đã tiếp nhận tranh chấp.",DisputeStatuses.Cancelled=>"Đã hủy tranh chấp.",_=>"Đã lưu kết luận và thông báo hai bên."});
 }
 private async Task<IReadOnlyList<DisputeCaseItem>> LoadCasesAsync(Guid? userId,bool isBrand,string? status,CancellationToken ct,Topstar.Application.Common.ListWindow? window=null,Guid? campaignId=null)
 {
  var rows=await(from d in db.DisputeCases.AsNoTracking() join p in db.Participations.AsNoTracking() on d.ParticipationId equals p.Id join c in db.Campaigns.AsNoTracking() on p.CampaignId equals c.Id join b in db.BrandProfiles.AsNoTracking() on c.BrandProfileId equals b.Id join k in db.KocProfiles.AsNoTracking() on p.KocProfileId equals k.Id join u in db.Users.AsNoTracking() on d.CreatedByUserId equals u.Id where (!userId.HasValue||(isBrand?b.UserId==userId:k.UserId==userId))&&(!campaignId.HasValue||c.Id==campaignId.Value)&&(string.IsNullOrEmpty(status)||d.Status==status) orderby d.IsActive descending,d.Priority=="High"?0:1,d.CreatedAtUtc descending select new{Case=d,c.Title,CampaignStatus=c.Status,Brand=b.CompanyName,Koc=k.DisplayName,OpenedBy=u.Email}).ToWindowAsync(window,ct,q=>q.Where(x=>(window!.Search==null||x.Title.Contains(window.Search)||x.Case.Subject.Contains(window.Search)||x.Brand.Contains(window.Search)||x.Koc.Contains(window.Search))&&(window.Status==null||x.Case.Status==window.Status)),x=>x.Case.Status);
  var ids=rows.Select(x=>x.Case.Id).ToArray();var histories=await db.DisputeCaseStatusHistories.AsNoTracking().Where(x=>ids.Contains(x.DisputeCaseId)).OrderBy(x=>x.CreatedAtUtc).ToListAsync(ct);var map=histories.GroupBy(x=>x.DisputeCaseId).ToDictionary(g=>g.Key,g=>(IReadOnlyList<DisputeHistoryItem>)g.Select(h=>new DisputeHistoryItem(h.FromStatus,h.ToStatus,h.Note,h.CreatedAtUtc)).ToList());return rows.Select(x=>new DisputeCaseItem(x.Case.Id,x.Title,x.CampaignStatus,x.Brand,x.Koc,x.Case.Category,x.Case.Subject,x.Case.Description,x.Case.Status,x.Case.Priority,x.OpenedBy??"Người dùng",x.Case.ResolutionNote,x.Case.CreatedAtUtc,map.GetValueOrDefault(x.Case.Id,[]))).ToList();
 }
 private void History(Guid id,string? from,string to,string? note,Guid actor,DateTime now)=>db.DisputeCaseStatusHistories.Add(new(){Id=Guid.NewGuid(),DisputeCaseId=id,FromStatus=from,ToStatus=to,Note=note,ActorUserId=actor,CreatedAtUtc=now});private void Notify(Guid user,string audienceRole,string type,string title,string body,Guid sourceId,DateTime now)=>db.Notifications.Add(Topstar.Infrastructure.Notifications.NotificationFactory.Create(user,type,title,body,now,"DisputeCase",sourceId,audienceRole:audienceRole));private void Audit(Guid actor,Guid id,string action,object payload,DateTime now)=>db.AuditLogs.Add(new(){ActorUserId=actor,EntityName="DisputeCase",EntityId=id.ToString(),ActionName=action,PayloadJson=JsonSerializer.Serialize(payload),CreatedAtUtc=now});private static string NormalizeCategory(string? s)=>DisputeCategories.All.FirstOrDefault(x=>x.Equals(Clean(s),StringComparison.OrdinalIgnoreCase))??"";private static string? Clean(string? s)=>string.IsNullOrWhiteSpace(s)?null:s.Trim();private static DisputeResult Ok(string m)=>new(true,m);private static DisputeResult Fail(string m)=>new(false,m);
}
